import json,glob
for f in sorted(glob.glob('**/*',recursive=True)):
    import os
    if os.path.isdir(f): continue
    d=json.load(open(f))
    def walk(o):
        if isinstance(o,dict):
            for k,v in o.items(): yield from walk(v)
        elif isinstance(o,list):
            for v in o: yield from walk(v)
        else: yield o
    nums=[x for x in walk(d) if isinstance(x,(int,float)) and not isinstance(x,bool)]
    nonascii=[x for x in walk(d) if isinstance(x,str) and any(ord(c)>126 for c in x)]
    print(f, 'nums=',set(map(repr,nums)), 'nonascii=',nonascii)
"

