// Black-box equivalence harness for /output/lib/referencing/metaschemas.mjs
//
// For every bundled meta-schema URI U with candidate document M, and for every
// probe instance I, these two invocations must produce identical 3-line output:
//
//   A: test13_executable --a I --b {"$schema": M.$schema, "$ref": U}
//   B: test13_executable --a I --b M
//
// The explicit "$schema" in A is required only so that line 1 (the validator
// class chosen by validator_for on the *top-level* schema) matches; without it
// A always reports Draft202012Validator while B reports the dialect declared by
// the document itself. Lines 2 and 3 (validity and top-level error count) are
// unaffected by that wrapper: jsonschema's $ref evolves to the dialect of the
// resolved resource and yields its errors un-wrapped.
//
// Usage: node /workspace/probes/meta/verify.mjs [--uri <substr>] [--jobs N]

import { execFile } from 'node:child_process';
import { CORPUS } from './corpus.mjs';
import { METASCHEMAS } from '/output/lib/referencing/metaschemas.mjs';

const EXE = '/workspace/dataset/test13_executable';

const argv = process.argv.slice(2);
const filter = argv.includes('--uri') ? argv[argv.indexOf('--uri') + 1] : null;
const JOBS = argv.includes('--jobs') ? Number(argv[argv.indexOf('--jobs') + 1]) : 24;

function run(a, b) {
  return new Promise((resolve) => {
    execFile(EXE, ['--a', a, '--b', b], { maxBuffer: 1 << 24 }, (err, stdout, stderr) => {
      if (err) resolve({ ok: false, out: `ERROR(${err.code}) ${String(stderr).slice(0, 400)}` });
      else resolve({ ok: true, out: stdout.trim() });
    });
  });
}

async function pool(tasks, n) {
  const results = new Array(tasks.length);
  let i = 0;
  await Promise.all(
    Array.from({ length: Math.min(n, tasks.length) }, async () => {
      for (;;) {
        const k = i++;
        if (k >= tasks.length) return;
        results[k] = await tasks[k]();
      }
    })
  );
  return results;
}

const uris = Object.keys(METASCHEMAS).filter((u) => !filter || u.includes(filter));
const instances = CORPUS.map((v) => JSON.stringify(v));

console.log(`URIs: ${uris.length}   probe instances: ${instances.length}   invocations: ${uris.length * instances.length * 2}`);

let mismatches = 0;
let checks = 0;
const failures = [];

for (const uri of uris) {
  const doc = METASCHEMAS[uri];
  const dialect = doc['$schema'];
  if (typeof dialect !== 'string') {
    console.log(`!! ${uri}: document has no string $schema`);
    mismatches++;
    continue;
  }
  const schemaA = JSON.stringify({ $schema: dialect, $ref: uri });
  const schemaB = JSON.stringify(doc);

  const tasks = [];
  for (const inst of instances) {
    tasks.push(async () => {
      const [ra, rb] = await Promise.all([run(inst, schemaA), run(inst, schemaB)]);
      return { inst, ra, rb };
    });
  }
  const res = await pool(tasks, JOBS);
  let bad = 0;
  for (const { inst, ra, rb } of res) {
    checks++;
    if (ra.out !== rb.out) {
      bad++;
      mismatches++;
      if (failures.length < 40) {
        failures.push(
          `MISMATCH ${uri}\n  instance: ${inst}\n  A(ref)  : ${JSON.stringify(ra.out)}\n  B(inline): ${JSON.stringify(rb.out)}`
        );
      }
    }
  }
  console.log(`${bad === 0 ? 'OK  ' : 'FAIL'} ${uri}  (${res.length} probes, ${bad} mismatches)`);
}

for (const f of failures) console.log('\n' + f);
console.log(`\nTOTAL: ${checks} comparisons, ${mismatches} mismatches`);
process.exit(mismatches === 0 ? 0 : 1);

// Negative control: deliberately corrupt each candidate document and confirm
// the A-vs-B comparison used by verify.mjs actually detects the difference.
import { execFile } from 'node:child_process';
import { CORPUS } from './corpus.mjs';
import { METASCHEMAS } from '/output/lib/referencing/metaschemas.mjs';

const EXE = '/workspace/dataset/test13_executable';
const run = (a, b) =>
  new Promise((res) =>
    execFile(EXE, ['--a', a, '--b', b], { maxBuffer: 1 << 24 }, (e, o, s) =>
      res(e ? `ERROR ${String(s).slice(0, 120)}` : o.trim())
    )
  );

const clone = (o) => JSON.parse(JSON.stringify(o));

const MUTATIONS = [
  ['http://json-schema.org/draft-03/schema#', 'drop root "dependencies"', (d) => { delete d.dependencies; }],
  ['http://json-schema.org/draft-04/schema#', 'drop properties.exclusiveMaximum', (d) => { delete d.properties.exclusiveMaximum; }],
  ['http://json-schema.org/draft-06/schema#', 'positiveInteger minimum 0 -> 1', (d) => { d.definitions.nonNegativeInteger.minimum = 1; }],
  ['http://json-schema.org/draft-07/schema#', 'drop properties.multipleOf', (d) => { delete d.properties.multipleOf; }],
  ['http://json-schema.org/draft-07/schema#', 'stringArray uniqueItems -> false', (d) => { d.definitions.stringArray.uniqueItems = false; }],
  ['https://json-schema.org/draft/2019-09/schema', 'drop one allOf branch', (d) => { d.allOf.splice(2, 1); }],
  ['https://json-schema.org/draft/2019-09/meta/core', 'drop properties.$anchor pattern', (d) => { delete d.properties.$anchor.pattern; }],
  ['https://json-schema.org/draft/2019-09/meta/validation', 'drop properties.required', (d) => { delete d.properties.required; }],
  ['https://json-schema.org/draft/2019-09/meta/applicator', 'items -> plain schema', (d) => { d.properties.items = { $recursiveRef: '#' }; }],
  ['https://json-schema.org/draft/2019-09/meta/meta-data', 'drop properties.deprecated', (d) => { delete d.properties.deprecated; }],
  ['https://json-schema.org/draft/2019-09/meta/format', 'format type -> integer', (d) => { d.properties.format.type = 'integer'; }],
  ['https://json-schema.org/draft/2019-09/meta/content', 'drop contentSchema', (d) => { delete d.properties.contentSchema; }],
  ['https://json-schema.org/draft/2020-12/schema', 'drop one allOf branch', (d) => { d.allOf.splice(0, 1); }],
  ['https://json-schema.org/draft/2020-12/meta/core', 'drop $defs.anchorString', (d) => { d.properties.$anchor = { type: 'string' }; }],
  ['https://json-schema.org/draft/2020-12/meta/applicator', 'drop prefixItems', (d) => { delete d.properties.prefixItems; }],
  ['https://json-schema.org/draft/2020-12/meta/unevaluated', 'drop unevaluatedItems', (d) => { delete d.properties.unevaluatedItems; }],
  ['https://json-schema.org/draft/2020-12/meta/validation', 'multipleOf exclusiveMinimum 0 -> 1', (d) => { d.properties.multipleOf.exclusiveMinimum = 1; }],
  ['https://json-schema.org/draft/2020-12/meta/meta-data', 'examples items -> string', (d) => { d.properties.examples.items = { type: 'string' }; }],
  ['https://json-schema.org/draft/2020-12/meta/format-annotation', 'format type -> array', (d) => { d.properties.format.type = 'array'; }],
  ['https://json-schema.org/draft/2020-12/meta/content', 'contentMediaType type -> number', (d) => { d.properties.contentMediaType.type = 'number'; }],
  ['https://json-schema.org/draft/2020-12/meta/format-assertion', 'drop $vocabulary', (d) => { delete d.$vocabulary; }],
];

const instances = CORPUS.map((v) => JSON.stringify(v));
let undetected = 0;

for (const [uri, label, mutate] of MUTATIONS) {
  const good = METASCHEMAS[uri];
  const bad = clone(good);
  mutate(bad);
  const schemaA = JSON.stringify({ $schema: good['$schema'], $ref: uri });
  const schemaB = JSON.stringify(bad);
  let detected = 0;
  // limited concurrency
  const chunk = 32;
  for (let i = 0; i < instances.length; i += chunk) {
    const slice = instances.slice(i, i + chunk);
    const outs = await Promise.all(
      slice.map(async (inst) => [inst, await run(inst, schemaA), await run(inst, schemaB)])
    );
    for (const [, a, b] of outs) if (a !== b) detected++;
  }
  if (detected === 0) undetected++;
  console.log(`${detected > 0 ? 'detected' : 'MISSED  '}  ${uri}  [${label}]  ${detected}/${instances.length} probes differ`);
}
console.log(`\nundetected mutations: ${undetected} / ${MUTATIONS.length}`);
process.exit(undetected === 0 ? 0 : 1);

